use std::fmt::Debug;
use std::hash::Hash;

/// The id of one thing of a kind the game is made of: a variant per file
/// in the kind's folder in `assets`, generated by `build.rs` (see
/// `content::catalog`).
pub trait CatalogId: Copy + Eq + Hash + Debug + Send + Sync + 'static {
    /// The kind's folder in `assets`.
    const FOLDER: &'static str;
    /// Every one, in file name order.
    const ALL: &'static [Self];
    /// Each one's file name (without its extension), in the same order.
    const FILES: &'static [&'static str];

    fn index(self) -> usize;

    /// Its file name (without its extension).
    fn file(self) -> &'static str {
        Self::FILES[self.index()]
    }

    /// Where its file is, for messages: `assets/weapons/sweep.ron`.
    fn path(self) -> String {
        format!("assets/{}/{}.ron", Self::FOLDER, self.file())
    }
}

include!(concat!(env!("OUT_DIR"), "/catalog_ids.rs"));
